UPDATE iep_programs SET title = #{title}, academic_year = #{academicYear},
    start_date = #{startDate}, end_date = #{endDate},
    present_levels = #{presentLevels}, accommodations = #{accommodations}, status = #{status}
WHERE id = #{id}

UPDATE iep_goals SET domain = #{domain}, description = #{description},
    target_date = #{targetDate}, status = #{status}, progress_pct = #{progressPct}
WHERE id = #{id}
